type Id = string | number;

interface Organization {
  id: Id;
  [key: string]: unknown;
}

interface User {
  id: Id;
  orgId: Id;
  org?: Organization;
  [key: string]: unknown;
}

async function loadUser(id: Id): Promise<User> {
  const userRes = await fetch(`/api/users/${id}`);
  if (!userRes.ok) {
    throw new Error(`Failed to load user ${id}: HTTP ${userRes.status}`);
  }

  let user: User;
  try {
    user = (await userRes.json()) as User;
  } catch {
    throw new Error(`Invalid JSON response for user ${id}`);
  }

  if (!user || typeof user !== "object" || user.orgId === undefined) {
    throw new Error(`Invalid user payload for ${id}`);
  }

  const orgRes = await fetch(`/api/orgs/${user.orgId}`);
  if (!orgRes.ok) {
    throw new Error(`Failed to load org ${user.orgId} for user ${id}: HTTP ${orgRes.status}`);
  }

  let org: Organization;
  try {
    org = (await orgRes.json()) as Organization;
  } catch {
    throw new Error(`Invalid JSON response for org ${user.orgId}`);
  }

  user.org = org;
  return user;
}

async function loadUsers(ids: Id[]): Promise<User[]> {
  return Promise.all(ids.map((id) => loadUser(id)));
}

export { loadUser, loadUsers };
